WITH "m0" AS ( INSERT INTO "public"."mutation_item" AS "s" ( "id" ) VALUES ( DEFAULT ) , ( DEFAULT ) RETURNING "s" AS "t0" , NULL::tid AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "t0"."score" AS "score" ) AS "%")) ), '[]') FROM "r0" AS "t0" ) )
